/** Optional current gameplay controls from a decoded save root.
 * Zero is an active selection, not a missing value. Orb distances remain raw
 * save scalars: this reader does not establish their world/display units.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    decodeLifeSavingOrder, readRuntimeControlsFromSaveRoot
 * depends    src/save/runtime-controls/constants, src/save/runtime-controls/types
 * used by    src/calculators/specs.generated, src/save/runtime-controls/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import { LIFE_SAVING_EFFECT_NAMES_BY_ID } from './constants'
import type { LifeSavingEffectName, RuntimeControlsSaveExtract } from './types'

function validOrder(value: unknown): value is number[] {
  return Array.isArray(value) && value.length <= 32
    && value.every(id => typeof id === 'number' && Number.isFinite(id) && Number.isInteger(id) && id >= 0)
    && new Set(value).size === value.length
}

/** Decodes known dispatch IDs in saved order. Unknown IDs retain their raw ID
 * and a null name for forward compatibility. Invalid or absent orders are null.
 * Names do not imply that any particular simulator implements the handler.
 */
export function decodeLifeSavingOrder(order: readonly number[] | null | undefined):
  { id: number; name: LifeSavingEffectName | null }[] | null {
  if (!validOrder(order)) return null
  return order.map(id => ({ id, name: Object.prototype.hasOwnProperty.call(LIFE_SAVING_EFFECT_NAMES_BY_ID, id)
    ? LIFE_SAVING_EFFECT_NAMES_BY_ID[id as keyof typeof LIFE_SAVING_EFFECT_NAMES_BY_ID] : null }))
}

/** Reads exact decoded-root names without coercion, defaults or unit conversion.
 * Missing and malformed fields are null and named in unreadableKeys.
 */
export function readRuntimeControlsFromSaveRoot(root: Record<string, unknown> | null): RuntimeControlsSaveExtract | null {
  if (!root) return null
  const unreadableKeys: string[] = []
  const numeric = (key: string, integer = false): number | null => {
    const value = root[key]
    if (typeof value === 'number' && Number.isFinite(value) && value >= 0
      && (!integer || Number.isInteger(value))) return value
    unreadableKeys.push(key)
    return null
  }
  const flag = (key: string): boolean | null => {
    const value = root[key]
    if (typeof value === 'boolean') return value
    unreadableKeys.push(key)
    return null
  }
  const order = (key: string): number[] | null => {
    const value = root[key]
    if (validOrder(value)) return [...value]
    unreadableKeys.push(key)
    return null
  }
  return {
    rangeLevelSelected: numeric('rangeLevelSelected', true),
    swampRangeLevelSelected: numeric('swampRangeLevelSelected', true),
    poisonSwampStunOff: flag('poisonSwampStunOff'),
    innerOrbDistance: numeric('innerOrbDistance'),
    workshopOrbDistance: numeric('workshopOrbDistance'),
    savedWorkshopOrbDistance: numeric('savedWorkshopOrbDistance'),
    savedInnerOrbDistance: numeric('savedInnerOrbDistance'),
    lifeSavingOrder: order('lifeSavingOrder'),
    energyShieldRestrictionToggle: flag('energyShieldRestrictionToggle'),
    targetPriority: numeric('targetPriority', true),
    targetPriorityList: (() => {
      const value = root.targetPriorityList
      if (Array.isArray(value) && value.length <= 64 && value.every(item =>
        typeof item === 'number' && Number.isSafeInteger(item) && item >= 0 && item <= 255)) return [...value]
      unreadableKeys.push('targetPriorityList')
      return null
    })(),
    unreadableKeys,
  }
}
